# Lessons 1-6 (exec'd by lfa_teorie.py): languages, regular expressions, DFA, NFA,
# closure properties, automata <-> expressions.

# =============================================================================
# 1. Languages
# =============================================================================
lesson('limbaje', 'Alfabete, cuvinte și limbaje',
       'Vocabularul întregului curs: alfabet, cuvânt, cuvântul vid, concatenare, prefix și sufix, limbaj, operațiile cu limbaje și steaua lui Kleene; de ce există limbaje pe care nicio mașină nu le poate descrie.',
       'Curs 1–2', 20, [
    sec('de-ce', 'Ce studiază cursul',
        p('Teoria automatelor întreabă **ce se poate calcula** și **cu câtă memorie**. Ca să putem răspunde riguros, orice problemă e transformată într-o întrebare despre cuvinte: „cuvântul `w` aparține mulțimii `L`?” Un program care răspunde la întrebare **recunoaște** limbajul `L`.'),
        p('Cursul urcă pe o scară de modele de calcul, fiecare cu mai multă memorie decât precedentul:'),
        tab(['model', 'memorie', 'limbaje recunoscute', 'descriere echivalentă'], [
            ['automat finit (AFD, AFN)', 'un număr fix de stări', 'regulate (LR)', 'expresii regulate, gramatici regulate'],
            ['automat cu stivă (APD)', 'stări + o stivă nemărginită', 'independente de context (LIC)', 'gramatici independente de context'],
            ['mașina Turing', 'o bandă nemărginită, citire și scriere', 'Turing acceptate / decidabile', 'gramatici fără restricții'],
        ]),
        note('Pentru fiecare clasă cursul cere aceleași patru lucruri: **definiția** modelului, **echivalențele** (automat ↔ expresie/gramatică), **proprietățile de închidere** (ce operații păstrează clasa) și **proprietățile algoritmice** (ce întrebări au algoritm). Plus o unealtă pentru a arăta că un limbaj **nu** e în clasă: lemele de pompare, respectiv nedecidabilitatea.', 'exam'),
        ),
    sec('cuvinte', 'Alfabet și cuvinte',
        d('Alfabet', 'Un **alfabet** `Σ` este o mulțime finită și nevidă de simboluri. Exemple: `{0, 1}`, `{a, b, c}`, caracterele ASCII.'),
        d('Cuvânt (șir)', 'Un **cuvânt** peste `Σ` este o secvență finită de simboluri din `Σ`. Lungimea lui, `|w|`, este numărul de simboluri. **Cuvântul vid**, notat `e` în curs (`ε` în multe cărți și în aplicație), are lungimea 0. `Σ*` este mulțimea tuturor cuvintelor peste `Σ`, iar `Σ⁺ = Σ* \\ {e}`.'),
        p('Notații pe care le folosesc grilele: `|w|ₐ` sau `#a(w)` este numărul de apariții ale lui `a` în `w`; `w(i)` este al `i`-lea simbol; `#ab(w)` numărul de apariții ale subcuvântului `ab`.'),
        d('Concatenare și puteri', 'Concatenarea `x · y` (sau `xy`) pune cuvintele unul după altul: `|xy| = |x| + |y|`. E asociativă, are elementul neutru `e` (`ew = we = w`) și **nu** e comutativă (`ab ≠ ba`). Puterile: `w⁰ = e`, `wⁱ⁺¹ = wⁱw`; de exemplu `(ab)³ = ababab`.'),
        d('Prefix, sufix, subcuvânt, oglindire', '`x` e **prefix** al lui `w` dacă `w = xy`, **sufix** dacă `w = yx`, **subcuvânt** (subsecvență contiguă) dacă `w = uxv`. `e` și `w` sunt prefixe (și sufixe) ale lui `w`. **Oglinditul** (răsturnatul) `wᴿ` se citește de la coadă: `(abb)ᴿ = bba`; `(xy)ᴿ = yᴿxᴿ`. Un **palindrom** are `w = wᴿ`.'),
        ex('Câte prefixe are un cuvânt?', 'Câte prefixe are `w = abba`? Dar câte subcuvinte distincte?',
           'Prefixele sunt `e, a, ab, abb, abba`: în general `|w| + 1`. Subcuvintele distincte: `e`, `a`, `b`, `ab`, `bb`, `ba`, `abb`, `bba`, `abba`: 9 (se numără o singură dată fiecare șir, chiar dacă apare de mai multe ori).'),
        ),
    sec('limbaje', 'Limbaje și operațiile lor',
        d('Limbaj', 'Un **limbaj** peste `Σ` este orice submulțime `L ⊆ Σ*`, finită sau infinită. `∅` (limbajul vid, fără niciun cuvânt) și `{e}` (doar cuvântul vid) sunt limbaje **diferite**.'),
        p('Fiind mulțimi, limbajele au operațiile obișnuite: reuniune `L1 ∪ L2`, intersecție `L1 ∩ L2`, diferență `L1 \\ L2`, complement `∁L = Σ* \\ L` (în curs, `L` cu o bară deasupra). În plus, cele care folosesc structura cuvintelor:'),
        tab(['operație', 'definiție', 'exemplu'], [
            ['concatenare', '`L1L2 = {xy | x ∈ L1, y ∈ L2}`', '`{a, ab}{b, e} = {ab, a, abb}`'],
            ['putere', '`L⁰ = {e}`, `Lⁱ⁺¹ = LⁱL`', '`{a, b}² = {aa, ab, ba, bb}`'],
            ['steaua lui Kleene', '`L* = L⁰ ∪ L¹ ∪ L² ∪ …`', '`{ab}* = {e, ab, abab, …}`'],
            ['plus', '`L⁺ = LL* = L¹ ∪ L² ∪ …`', '`{a}⁺ = {a, aa, …}`'],
            ['oglindire', '`Lᴿ = {wᴿ | w ∈ L}`', '`{ab, abb}ᴿ = {ba, bba}`'],
            ['prefixe', '`prefix(L) = {x | ∃y, xy ∈ L}`', '`prefix({ab}) = {e, a, ab}`'],
        ]),
        note('`∅* = {e}` (puterea 0 e întotdeauna `{e}`), `L∅ = ∅L = ∅`, `L{e} = L`. Iar `e ∈ L*` pentru **orice** `L`. Aceste trei reguli rezolvă o grămadă de grile de tipul „ce limbaj este …”.', 'warn'),
        quiz('Ce este `∅*`?', ['`∅`', '`{e}`', '`Σ*`', 'nu e definit'], 1, 'Steaua conține mereu `L⁰ = {e}`; celelalte puteri ale lui `∅` sunt vide.'),
        quiz('Fie `L = {a, ab}`. Este `L* = {a, b}*`?', ['da', 'nu: `b ∈ {a, b}*`, dar `b ∉ L*`', 'nu: `e ∉ L*`'], 1,
             'Orice cuvânt din `L*` e concatenare de `a` și `ab`, deci începe cu `a` (sau e vid) și nu are `bb`. `b` nu se obține.'),
        ),
    sec('numarare', 'Câte limbaje există? (de ce unele nu se pot calcula)',
        thm('Cardinalități', '`Σ*` este **infinit numărabilă**: cuvintele se pot lista în ordinea lungimii, apoi lexicografic (`e, a, b, aa, ab, …`). Mulțimea tuturor limbajelor, `2^(Σ*)`, este **nenumărabilă**.',
            'Prin diagonalizare (Cantor): presupunem că limbajele se pot lista `L0, L1, L2, …` și fie `w0, w1, …` lista cuvintelor. Limbajul `D = {wᵢ | wᵢ ∉ Lᵢ}` diferă de fiecare `Lᵢ` prin cuvântul `wᵢ`, deci nu e în listă: contradicție.', label='Propoziție'),
        p('Consecința e fundamentală: orice automat, expresie, gramatică sau program este un **text finit**, deci există doar numărabil de multe descrieri. Cum limbajele sunt nenumărabile, **majoritatea limbajelor nu au nicio descriere finită**: nicio mașină nu le poate recunoaște.'),
        note('Grile frecvente: „Mulțimea limbajelor regulate / LIC / Turing acceptate este …” → **infinit numărabilă** (sunt infinit de multe, dar fiecare are o descriere finită). „Mulțimea tuturor limbajelor peste Σ este …” → **nenumărabilă**.', 'exam'),
        quiz('Cum este mulțimea limbajelor independente de context peste un alfabet `Σ = {i}`?', ['finită', 'infinit numărabilă', 'nenumărabilă', 'nu se poate afirma nimic'], 1,
             'Fiecare LIC are o gramatică (text finit), deci sunt numărabile; și sunt infinit de multe, de exemplu `{iⁿ}` pentru fiecare `n`.'),
        ),
], practice=['40', '191'])

