lesson('afd', 'Automate finite deterministe',
       'Primul model de calcul: o mașină cu un număr finit de stări care citește cuvântul o singură dată, de la stânga la dreapta. Definiția formală, configurații și calcul, diagrame, și metoda de construcție „ce trebuie să țină minte starea?”.',
       'Curs 2', 30, [
    sec('definitie', 'Definiția',
        d('AFD', 'Un **automat finit determinist** este un tuplu `M = (K, Σ, δ, s, F)`:\n- `K` – mulțimea finită a stărilor;\n- `Σ` – alfabetul de intrare;\n- `δ : K × Σ → K` – funcția de tranziție, **totală**: pentru fiecare stare și fiecare simbol există exact o stare următoare;\n- `s ∈ K` – starea inițială;\n- `F ⊆ K` – mulțimea stărilor finale (de acceptare).'),
        d('Configurație și pas de calcul', 'O **configurație** e o pereche `(q, w) ∈ K × Σ*`: starea curentă și ce a mai rămas de citit. Un pas: `(q, aw) ⊢ (δ(q, a), w)`. `⊢*` e închiderea reflexivă și tranzitivă (zero sau mai mulți pași).'),
        d('Acceptare', '`M` **acceptă** `w` dacă `(s, w) ⊢* (f, e)` pentru o stare `f ∈ F`. Limbajul `L(M)` e mulțimea cuvintelor acceptate. Un limbaj e **regulat** dacă e acceptat de un automat finit.'),
        note('`δ` totală înseamnă că un AFD are **exact** `|K| · |Σ|` tranziții (o grilă întreabă minimul și maximul: amândouă sunt `|K| · |Σ|`). Când într-o diagramă „lipsesc” tranziții, ele duc implicit într-o **groapă** (o stare nefinală din care nu mai ieși).', 'exam'),
        ),
    sec('exemplu', 'Un automat la lucru',
        p('Automatul de mai jos acceptă cuvintele peste `{a, b}` care **se termină cu** `ab`. Starea ține minte cât din sufixul `ab` s-a văzut: `q0` nimic, `q1` un `a` la coadă, `q2` exact `ab` la coadă (finală).'),
        viz('automaton', 'Citește un cuvânt pas cu pas',
            'Alege un cuvânt și apasă ▶ (sau „redă”). Starea aprinsă e cea curentă, săgeata aprinsă e tranziția folosită; dedesubt, șirul de configurații scris ca în curs.',
            alphabet='ab', a=ENDS_AB, pos=[[0, 0], [1.6, 0], [3.2, 0]], words=['aab', 'abab', 'aba', 'b', '']),
        ex('Configurațiile pentru `aab`', 'Scrie calculul automatului de mai sus pe `aab`.',
           '`(q0, aab) ⊢ (q1, ab) ⊢ (q1, b) ⊢ (q2, e)`, iar `q2 ∈ F`, deci `aab ∈ L(M)`.', open_=True),
        ),
    sec('constructie', 'Cum construiești un AFD',
        p('Întrebarea-cheie: **ce informație despre prefixul citit trebuie păstrată** ca să poți decide la final? Fiecare valoare posibilă a acestei informații devine o stare. Informația trebuie să aibă un număr **finit** de valori și să se poată actualiza simbol cu simbol.'),
        steps('Metoda',
              'Descrie în cuvinte ce ține minte fiecare stare („numărul de `a` e impar”, „ultimele două simboluri sunt `ab`”).',
              'Starea inițială = informația pentru `e`.',
              'Pentru fiecare stare și fiecare simbol, calculează noua informație: aceasta e tranziția.',
              'Finale = stările a căror informație spune „cuvântul e în limbaj”.',
              'Verifică pe câteva cuvinte, inclusiv `e` și cuvinte care **nu** sunt în limbaj.'),
        ex('Numere binare divizibile cu 3', 'Un cuvânt peste `{0, 1}` este un număr în baza 2. Construiește un AFD pentru numerele divizibile cu 3.',
           'Ține minte restul `r` al valorii citite până acum. Dacă valoarea e `v` și vine bitul `c`, noua valoare e `2v + c`, deci noul rest e `(2r + c) mod 3`. Trei stări `q0, q1, q2`; `q0` inițială și finală.'),
        viz('automaton', 'Restul împărțirii la 3', '', alphabet='01', a=DIV3, pos=[[0, 0], [1.6, 0], [3.2, 0]], words=['110', '1001', '111', '0']),
        ex('Număr par de a și impar de b', 'Peste `{a, b}`.',
           'Patru stări: perechea (paritatea lui `#a`, paritatea lui `#b`). `a` schimbă prima componentă, `b` pe a doua. Finală: (par, impar). Aceasta e ideea **automatului produs**, pe care o vom formaliza la proprietățile de închidere.'),
        note('Complementul: într-un AFD **complet**, schimbând stările finale cu cele nefinale obții automatul pentru `Σ* \\ L`. Dacă automatul nu e complet, adaugă întâi groapa; altfel cuvintele care „se blochează” rămân respinse și în complement.', 'tip'),
        ),
    sec('verifica', 'Verifică-te',
        quiz('Fie `M` un AFD peste `|Σ| = 2` cu `k > 2` stări care acceptă orice șir cu `|w| ≤ k`. Atunci:', ['`|L(M)| ≤ 2ᵏ`', '`|L(M)| = 2ᵏ⁺¹ − 1`', '`L(M)` e infinit', '`L(M) = Σ*`'], 2,
             'Un cuvânt acceptat de lungime `k` trece prin `k + 1` stări, deci repetă una: există un ciclu pe un drum de acceptare, care se poate parcurge oricât. (Nu neapărat `Σ*`.)'),
        quiz('Fie `M1` un AFD care nu acceptă niciun șir. Atunci `M1`:', ['nu are stări finale', 'poate avea stări finale', 'are o singură stare', 'nu are cicluri'], 1,
             'Ajunge ca nicio stare finală să nu fie accesibilă din starea inițială.'),
        ),
], practice=ids('1.', kind='lfa') + ['159', '160', '163', '177'])

