lesson('afn', 'Automate nedeterministe și echivalența cu AFD',
       'Nedeterminismul: mai multe tranziții posibile, tranziții pe e, tranziții lipsă. De ce nu aduce putere în plus: ε-închiderea și construcția submulțimilor, rulată rând cu rând, plus costul ei (exponențial în cel mai rău caz).',
       'Curs 3', 35, [
    sec('definitie', 'Definiția din curs',
        d('AFN', 'Un **automat finit nedeterminist** este `M = (K, Σ, Δ, s, F)`, unde `Δ ⊆ K × Σ* × K` este o **relație** finită: tuplul `(q, u, p)` spune că din `q`, citind șirul `u`, automatul **poate** trece în `p`. Configurațiile sunt ca la AFD; `(q, uw) ⊢ (p, w)` dacă `(q, u, p) ∈ Δ`. `M` acceptă `w` dacă **există** un calcul `(s, w) ⊢* (f, e)` cu `f ∈ F`.'),
        p('Față de AFD, un AFN poate avea: mai multe tranziții pe același simbol, **tranziții pe `e`** (fără să citească nimic), **tranziții lipsă** (calculul se blochează și ramura respinge), și **tranziții pe șiruri** (`(q, ab, p)`). Un cuvânt e acceptat dacă **cel puțin o** ramură de calcul îl duce într-o stare finală cu tot cuvântul citit.'),
        note('Grile clasice: `Δ` e **finită**, dar pentru `K` și `Σ` date nu are o margine superioară (etichetele pot fi oricât de lungi); poate fi vidă. Un AFN poate avea **0 stări finale** (atunci acceptă `∅`). Un AFN care acceptă `e` **nu** trebuie să aibă starea inițială finală (poate ajunge într-o finală pe tranziții `e`).', 'exam'),
        viz('automaton', 'Un AFN citește: mulțimea stărilor posibile',
            'Al treilea simbol de la sfârșit este `a`. Din `q0`, la fiecare `a`, automatul „ghicește” dacă acesta e al treilea de la coadă. Toate stările aprinse sunt locuri în care automatul poate fi.',
            alphabet='ab', a=THIRD, pos=[[0, 0], [1.6, 0], [3.2, 0], [4.8, 0]], words=['abb', 'aaba', 'babab', 'ab']),
        ),
    sec('inchidere', 'Tranzițiile pe e și ε-închiderea',
        d('ε-închiderea', 'Pentru o stare `q`, `E(q)` = mulțimea stărilor în care se poate ajunge din `q` folosind doar tranziții pe `e` (inclusiv `q`). Pentru o mulțime, `E(Q) = ∪ E(q)`.'),
        viz('automaton', 'a*b*c* cu tranziții pe e', 'Observă că în pornire automatul e deja în toate cele patru stări: `E(q0) = {q0, q1, q2, q3}`.', alphabet='abc', a=EPS_N, pos=[[0, 0], [1.6, 0], [3.2, 0], [4.8, 0]], words=['abc', 'ac', 'ba', '']),
        p('Înainte de construcția submulțimilor, cursul elimină tranzițiile pe șiruri: `(q, a1a2…an, p)` devine un drum `q —a1→ r1 —a2→ … —an→ p` prin stări noi.'),
        ),
    sec('submultimi', 'Construcția submulțimilor (AFN → AFD)',
        thm('Echivalența AFN ↔ AFD', 'Pentru orice AFN `M` există un AFD `M′` cu `L(M′) = L(M)`.',
            'Fie `M = (K, Σ, Δ, s, F)` fără tranziții pe șiruri de lungime > 1. Construim `M′ = (2^K, Σ, δ′, E(s), F′)` cu `δ′(Q, a) = ∪{E(p) | ∃q ∈ Q, (q, a, p) ∈ Δ}` și `F′ = {Q | Q ∩ F ≠ ∅}`. Prin inducție pe `|w|`: `(E(s), w) ⊢*_M′ (Q, e)` ⇔ `Q` este exact mulțimea stărilor `p` cu `(s, w) ⊢*_M (p, e)`. Deci `M′` acceptă ⇔ una dintre stările în care poate fi `M` e finală ⇔ `M` acceptă.'),
        steps('Algoritmul (ca în seminar)',
              'Starea inițială a AFD-ului: `E(s)`.',
              'Pentru o stare nouă `Q` și fiecare simbol `a`: reunește stările în care duce `a` din fiecare `q ∈ Q`, apoi aplică `E`. Rezultatul e `δ′(Q, a)`.',
              'Orice mulțime care apare pentru prima dată devine o stare nouă și primește și ea un rând.',
              'Te oprești când nu mai apar mulțimi noi. Finale: mulțimile care conțin o stare finală. Mulțimea vidă `∅`, dacă apare, e groapa.'),
        viz('subset', 'Construcția submulțimilor, rând cu rând',
            'AFN-ul de la examen: `N = ({0, 1}, {a, b}, {(0, a, 0), (0, b, 0), (0, b, 1), (1, a, 1), (1, a, 0)}, 0, {1})`. Apasă ▶: fiecare pas adaugă un rând tabelului și o stare AFD-ului.',
            alphabet='ab', a=EXAM_N, names=['0', '1'], pos=[[0, 0], [2, 0]]),
        viz('subset', 'Cu tranziții pe e', 'Aici coloana arată și mulțimea „înainte de închidere” → „după închidere”.', alphabet='abc', a=EPS_N, pos=[[0, 0], [1.6, 0], [3.2, 0], [4.8, 0]]),
        viz('subset', 'Explozia: se termină cu abb, apoi al treilea de la coadă', 'Un AFN cu `n + 1` stări pentru „al `n`-lea simbol de la sfârșit e `a`” dă un AFD cu `2ⁿ` stări, iar acesta e și minimul.', alphabet='ab', a=THIRD, pos=[[0, 0], [1.6, 0], [3.2, 0], [4.8, 0]]),
        note('Construcția poate produce până la `2^|K|` stări, dar în practică doar cele **accesibile** din `E(s)`. AFN-urile sunt utile tocmai pentru că pot fi exponențial mai mici. O grilă: „`M′` are cel puțin la fel de multe stări ca `M`?” – **fals** (AFN-ul poate avea stări inutile), dar „`M` poate avea mai multe stări decât `M′`” – **adevărat**.', 'exam'),
        exam('Examen LFA · set de probleme', 'Fie `N = ({0, 1}, {a, b}, Δ, 0, {1})` cu `Δ = {(0, a, 0), (0, b, 0), (0, b, 1), (1, a, 1), (1, a, 0)}`. Scrieți un automat determinist `A` astfel încât `L(N) = L(A)`, și o expresie regulată pentru limbaj.',
             '`E(0) = {0}`. `δ′({0}, a) = {0}`, `δ′({0}, b) = {0, 1}`; `δ′({0, 1}, a) = {0, 1}`, `δ′({0, 1}, b) = {0, 1}`. Două stări, `{0, 1}` finală. Limbajul: cuvintele care conțin un `b`, `a*b(a ∪ b)*`.'),
        ),
    sec('verifica', 'Verifică-te',
        quiz('Câte tupluri poate conține relația `Δ` a unui AFN (definiția din curs)?', ['cel mult `|K|²(|Σ| + 1)`', 'un număr finit, fără margine superioară', 'o infinitate', 'exact `|K||Σ|`'], 1,
             'Recapitularea seminarelor 1–4, problema 1. Etichetele sunt șiruri din `Σ*`, deci pot fi oricâte (dar finit). Bornă există doar dacă etichetele sunt simboluri sau `e`.'),
        quiz('Poate orice limbaj regulat să fie recunoscut de un AFD cu o singură stare finală?', ['da', 'nu', 'doar limbajele finite'], 1,
             '`{e, a}` peste `{a}`: starea inițială trebuie să fie finală (pentru `e`), apoi `δ(s, a)` e tot finală, deci aceeași stare, și se acceptă și `aa`. Un AFN, în schimb, poate avea mereu o singură stare finală (cu tranziții pe `e` spre ea).'),
        ),
], practice=ids('2.', kind='lfa') + ['100', '110', '111', '165', '173', '184', '185'])

