lesson('inchidere-lr', 'Proprietăți de închidere ale limbajelor regulate',
       'Ce operații transformă limbaje regulate tot în limbaje regulate, cu construcția de automat pentru fiecare: reuniune, concatenare, stea, complement, intersecție (automatul produs), diferență, oglindire, prefixe, sufixe, câtul. Și cum se folosesc ca să demonstrezi că un limbaj e regulat.',
       'Curs 4', 35, [
    sec('constructii', 'Construcțiile pentru reuniune, concatenare și stea',
        p('Fie `M1 = (K1, Σ, Δ1, s1, F1)` și `M2 = (K2, Σ, Δ2, s2, F2)` două AFN cu stări disjuncte. Construcțiile din curs:'),
        tab(['operație', 'automatul', 'ideea'], [
            ['`L1 ∪ L2`', 'stare nouă `s`; `Δ = Δ1 ∪ Δ2 ∪ {(s, e, s1), (s, e, s2)}`; `F = F1 ∪ F2`', 'ghicește de la început care automat'],
            ['`L1L2`', '`s = s1`; `Δ = Δ1 ∪ Δ2 ∪ {(f, e, s2) | f ∈ F1}`; `F = F2`', 'după un cuvânt din `L1`, sari în `M2`'],
            ['`L1*`', 'stare nouă `s′`, inițială și **finală**; `Δ = Δ1 ∪ {(s′, e, s1)} ∪ {(f, e, s1) | f ∈ F1}`; `F = F1 ∪ {s′}`', 'reia `M1` de oricâte ori; `e` acceptat'],
            ['`Σ* \\ L1`', 'AFD **complet**, `F = K \\ F1`', 'inversează verdictul'],
            ['`L1 ∩ L2`', 'automatul produs (mai jos) sau De Morgan: `∁L1 ∪ ∁L2` complementat', 'rulează ambele în paralel'],
        ]),
        note('La stea, starea nouă `s′` e necesară: dacă ai face pur și simplu `s1` finală, ai putea accepta cuvinte care nu sunt în `L1*` (când există tranziții care intră înapoi în `s1`).', 'warn'),
        ),
    sec('produs', 'Automatul produs: intersecție, reuniune, diferență, diferență simetrică',
        thm('Produsul', 'Pentru două AFD complete `M1`, `M2` peste același `Σ`, automatul `M = (K1 × K2, Σ, δ, (s1, s2), F)` cu `δ((p, q), a) = (δ1(p, a), δ2(q, a))` acceptă:\n- `L1 ∩ L2` pentru `F = F1 × F2`;\n- `L1 ∪ L2` pentru `F = (F1 × K2) ∪ (K1 × F2)`;\n- `L1 \\ L2` pentru `F = F1 × (K2 \\ F2)`;\n- `L1 △ L2` pentru perechile cu **exact una** dintre componente finală.',
            'Prin inducție pe `|w|`: `δ*((s1, s2), w) = (δ1*(s1, w), δ2*(s2, w))`. Deci perechea la care se ajunge spune, simultan, dacă `w ∈ L1` și dacă `w ∈ L2`; mulțimea `F` alege combinația dorită.'),
        viz('product', 'Produsul a două automate',
            'A: numărul de `a` e par. B: cuvântul se termină cu `b`. Schimbă operația: perechile rămân aceleași, se schimbă doar care sunt finale. Aceasta e și problema 5 din recapitularea seminarelor (diferența simetrică).',
            alphabet='ab', a=EVEN_A, b=checked(A(2, [1], '0 a 0\n0 b 1\n1 a 0\n1 b 1'), 'ab', lambda w: w.endswith('b')), op='△', la='#a par', lb='se termină cu b',
            posA=[[0, 0], [1.6, 0]], posB=[[0, 0], [1.6, 0]]),
        ),
    sec('altele', 'Oglindire, prefixe, sufixe, cât',
        tab(['limbaj', 'construcția'], [
            ['`Lᴿ`', 'întoarce toate săgețile; stare inițială nouă cu `e` spre fostele finale; finală devine fosta inițială'],
            ['`prefix(L)`', 'în AFD-ul lui `L`, fă finală orice stare din care se poate ajunge într-o stare finală'],
            ['`Suf(L)`', 'stare inițială nouă, cu `e` spre orice stare accesibilă din `s`'],
            ['`L1/L2 = {w | ∃x ∈ L2, wx ∈ L1}`', 'același automat ca pentru `L1`; finale devin stările `q` din care un cuvânt din `L2` duce în `F1`'],
            ['`{w ∈ L | w nu conține b}`', '`L ∩ (Σ \\ {b})*`'],
        ]),
        exam('Examen 9 iunie 2022', 'Fie `L1`, `L2` limbaje peste `Σ` și `L1 \\ L2 = {w ∈ Σ* | ∃x ∈ L2 a.î. wx ∈ L1}`. Demonstrați că dacă `L1` e regulat, atunci `L1 \\ L2` e regulat (`L2` oarecare!).',
             'Fie `M = (K, Σ, δ, s, F)` un AFD pentru `L1`. Definim `F′ = {q ∈ K | ∃x ∈ L2, δ*(q, x) ∈ F}` și `M′ = (K, Σ, δ, s, F′)`. Atunci `w ∈ L(M′)` ⇔ `δ*(s, w) ∈ F′` ⇔ `∃x ∈ L2` cu `δ*(δ*(s, w), x) ∈ F` ⇔ `∃x ∈ L2`, `wx ∈ L1`. `M′` are tot `|K|` stări, deci limbajul e regulat. (Nu știm neapărat să **calculăm** `F′` dacă `L2` e complicat, dar automatul există: demonstrația e de existență.)'),
        ),
    sec('folosire', 'Cum demonstrezi că un limbaj e regulat',
        steps('Rețeta pentru „Demonstrați că L e regulat”',
              'Scrie `L` ca o combinație de limbaje despre care știi că sunt regulate (finite, `Σ*`, `Σ*uΣ*`, „lungime pară”, limbajul unui automat dat), folosind operații la care LR sunt închise.',
              'Citează proprietatea de închidere la fiecare pas.',
              'Alternativ: construiește direct un AF (sau o ER) și explică de ce acceptă exact `L`.'),
        exam('Recapitulare seminarele 1–4, problema 4', 'Fie `Σ` un alfabet și `F ⊆ Σ*` finit. Arătați că `L = {w ∈ Σ* | w nu are subsecvențe în F}` e regulat.',
             '`L = Σ* \\ (Σ*FΣ*)`. `F` e finit, deci regulat; `Σ*` e regulat; concatenarea `Σ*FΣ*` e regulată; complementul ei e regulat. Același argument merge pentru orice `F` regulat (examenul din 2025 întreabă exact asta).'),
        exam('Examen 18 ianuarie 2025', 'Fie `L` regulat peste `{a, b, c}`. Arătați că `L′ = {w | w ∈ L ∧ #a(w) = 0}` e regulat.',
             '`L′ = L ∩ {b, c}*`. `{b, c}*` e regulat (expresia `(b ∪ c)*`), iar intersecția a două limbaje regulate e regulată.'),
        exam('Recapitulare seminarele 1–4, problema 8', 'Demonstrați că `Suf(L) = {w | ∃w′ ∈ L cu w sufix al lui w′}` e regulat atunci când `L` e regulat.',
             'Fie `M` un AFN pentru `L`. Construim `M′`: stările lui `M`, plus `s′` nouă inițială, cu `(s′, e, q)` pentru fiecare `q` accesibilă din `s`. Dacă `w ∈ Suf(L)`, `w′ = uw ∈ L`; calculul lui `M` pe `uw` trece după `u` printr-o stare `q`, deci `M′` sare în `q` și citește `w` până la o finală. Invers, un calcul acceptat de `M′` pornește dintr-un `q` accesibil, cu un `u` care duce în `q`, deci `uw ∈ L`.'),
        note('Capcana: închiderea merge într-un singur sens. `L1L2` regulat **nu** implică `L1`, `L2` regulate (`{0ⁿ1ᵐ | n > m} · 1* = 0⁺1*`); `L*` regulat nu implică `L` regulat (`{aᵖ | p prim}* = e ∪ aaa*`); `L1 ∪ L2` regulat nu implică nimic despre `L1` (`{0ⁱ1ʲ | i ≠ j} ∪ {0ⁱ1ⁱ} = 0*1*`). Și o submulțime a unui limbaj regulat poate fi oricât de complicată (`aⁿbⁿ ⊆ Σ*`).', 'warn'),
        quiz('`L1`, `L2` regulate. Care listă conține doar limbaje regulate?', ['`L1L2`, `L1 ∪ {0,1}*`, `L1 × L2`', '`L1*`, `2^(L1L2)`, `L2L1`', '`L1 ∪ L2`, `(L1 \\ L2) ∪ (L2 \\ L1)`, `L1 ∩ L2∅`', '`L2 × L1`, `L1 \\ L2`, `L2 \\ L1`'], 2,
             '`×` și `2^X` nu sunt limbaje (perechi de cuvinte, respectiv mulțimi de limbaje). Test 1, 2023.'),
        ),
], practice=ids('4.', limit=20))

