lesson('af-er', 'Echivalența automate ↔ expresii regulate',
       'Teorema lui Kleene în ambele sensuri: de la o expresie la un automat (construcția lui Thompson, bucată cu bucată) și de la un automat la o expresie (eliminarea stărilor, după ghidul CS103 de la Stanford, cu starea de eliminat aleasă de tine).',
       'Curs 4', 40, [
    sec('kleene', 'Teorema',
        thm('Kleene', 'Un limbaj este acceptat de un automat finit **dacă și numai dacă** este limbajul unei expresii regulate.',
            '(⇐) Prin inducție pe structura expresiei: `∅`, `e`, `a` au automate cu două stări; pentru `αβ`, `α ∪ β`, `α*` se aplică construcțiile de închidere la concatenare, reuniune și stea (construcția lui Thompson). (⇒) Prin eliminarea stărilor: se transformă automatul într-unul cu expresii pe săgeți și se elimină pe rând stările, păstrând limbajul, până rămâne o singură săgeată.'),
        ),
    sec('thompson', 'De la expresie la automat: construcția lui Thompson',
        p('Fiecare bucată a expresiei primește un automat cu **o singură stare de intrare și o singură stare de ieșire**:'),
        steps('Bucățile',
              '`a`: două stări, o săgeată `a`. `e`: o săgeată `e`. `∅`: două stări, nicio săgeată.',
              '`αβ`: ieșirea lui `α` se leagă cu `e` de intrarea lui `β`.',
              '`α ∪ β`: o intrare nouă cu `e` spre ambele, și o ieșire nouă în care intră `e` din ambele.',
              '`α*`: intrare și ieșire noi; `e` de la intrare la `α` și direct la ieșire (zero repetări); `e` de la ieșirea lui `α` înapoi la intrarea lui `α` (încă o repetare) și spre ieșire.'),
        viz('thompson', 'Construcția lui Thompson, bucată cu bucată',
            'Apasă ▶: se construiesc întâi bucățile cele mai mici, apoi cele care le conțin. Stările aprinse sunt intrarea și ieșirea bucății curente. Scrie altă expresie ca s-o vezi construită.',
            alphabet='ab', regex='(a∪b)*abb'),
        note('Automatul lui Thompson are cel mult `2 · |expresie|` stări și cel mult două săgeți care ies din fiecare stare. Nu e minimal, dar e mecanic: exact ce cere un exercițiu „construiți un AF pentru expresia …” (recapitularea seminarelor, problema 2).', 'tip'),
        ),
    sec('eliminare', 'De la automat la expresie: eliminarea stărilor',
        p('Ghidul CS103 (Stanford) descrie algoritmul în trei pași. Lucrăm cu un automat ale cărui săgeți poartă **expresii regulate**, nu doar simboluri.'),
        steps('Algoritmul',
              '**Pregătirea.** Adaugă o stare de start nouă `qs` cu `e` spre vechea stare inițială și o stare finală nouă `qf` cu `e` din fiecare veche stare finală; doar `qf` mai e finală. Săgețile paralele dintre aceleași două stări se unesc cu `∪`.',
              '**Eliminarea.** Cât timp mai există alte stări decât `qs` și `qf`, alege una, `q_gone`. Pentru fiecare pereche `(q_in, q_out)` cu o săgeată `q_in → q_gone` și una `q_gone → q_out` (ambele diferite de `q_gone`), adaugă săgeata `q_in → q_out` cu eticheta `R_in (R_buclă)* R_out`, unde `R_buclă` e bucla lui `q_gone` (fără buclă, doar `R_in R_out`). Dacă exista deja o săgeată `q_in → q_out` cu `R`, noua etichetă e `R ∪ R_in (R_buclă)* R_out`. Apoi șterge `q_gone`.',
              '**Citirea.** Au rămas `qs` și `qf`: expresia e eticheta săgeții `qs → qf` (sau `∅`, dacă nu există).'),
        viz('elim', 'Elimină stările, în ordinea aleasă de tine',
            '„Conține `aa`” (exercițiul din ghid). Atinge o stare ca s-o elimini, sau apasă butonul sugerat (cel care face expresiile cele mai scurte). Tabelul arată, pentru fiecare pereche, `R_in`, bucla, `R_out` și eticheta nouă.',
            alphabet='ab', a=HAS_AA, pos=[[0, 0], [1.8, 0], [3.6, 0]]),
        ex('Ordinea contează (pentru formă, nu pentru limbaj)', 'Elimină stările automatului de mai sus în ordinea `q2, q1, q0`, apoi în ordinea `q0, q1, q2`.',
           'Ordinea `q2, q1, q0` dă `(b ∪ ab)*aaΣ*` (ghidul scrie `(a?b)*aaΣ*`). Ordinea `q0, q1, q2` dă `b*a(b⁺a)*aΣ*`. Sunt expresii diferite pentru același limbaj, și niciuna nu e cea mai simplă: `Σ*aaΣ*`. Eliminarea stărilor garantează **o** expresie corectă, nu una frumoasă.'),
        viz('elim', 'Exemplul mare din ghid: paritatea adunării',
            'Limbajul `{aᵐ + aⁿ = aᵖ | m + n ≡ p (mod 2)}` peste `{a, +, =}` (în ghid, `≡` în loc de `=`; aici `+` e un **simbol**, nu operatorul). Rândul de sus: paritate pară până acum, cel de jos: impară. Ghidul elimină în ordinea `q3, q5, q4, q1, q2, q0`: încearcă și altă ordine.',
            alphabet='a+=', a=PARITY, pos=PARITY_POS, order=[3, 5, 4, 1, 2, 0]),
        note('Cum alegi ordinea: elimină întâi stările cu puține săgeți care intră și ies (produc puține perechi). Stările „de trecere”, cu o intrare și o ieșire, se elimină fără să crească expresia. Lasă la urmă stările cu bucle mari.', 'tip'),
        ),
    sec('verifica', 'Verifică-te',
        quiz('La eliminarea lui `q`, cu `q_in —x→ q`, buclă `y` pe `q`, `q —z→ q_out` și deja `q_in —w→ q_out`, noua etichetă `q_in → q_out` este:', ['`xyz`', '`w ∪ xy*z`', '`(w ∪ x)y*z`', '`w(xy*z)*`'], 1,
             'Drumurile vechi (`w`) rămân, iar cele prin `q` sunt intrare, oricâte bucle, ieșire.'),
        quiz('Ce expresie generează limbajul vid?', ['`1*`', '`1*∅`', '`∅*(∅ ∪ 0*)`', '`∅*`'], 1, '`x∅ = ∅`; `∅* = e`, deci `∅*` și `∅*(∅ ∪ 0*) = 0*` nu sunt vide.'),
        ),
], practice=['23', '101', '102', '103'] + ids('3.', mode='regex', limit=6))
